\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0,0);
\coordinate (B) at (4.8,0);
\coordinate (C) at (6.2,1.0);
\coordinate (D) at (1.4,1.0);
\coordinate (E) at (0,3.6);
\coordinate (F) at (4.8,3.6);
\coordinate (G) at (6.2,4.6);
