\draw (B) -- (C) node[midway, below right] {$5\text{ cm}$};
\draw (E) -- (A) node[midway, left] {$9\text{ cm}$};
\draw (C) -- (G) -- (F) -- (B);
\draw (E) -- (F) -- (G) -- (H) -- cycle;
\draw[dashed] (A) -- (D) -- (C);
\draw[dashed] (D) -- (H);
\draw (B) -- (G);
\draw[dashed] (B) -- (H);
